<script setup lang="ts">
import {ref,onMounted} from 'vue';import {api,session,money,date,type Row} from '../api';import Icon from '../components/Icon.vue';import Badge from '../components/Badge.vue'
const data=ref<Row|null>(null),error=ref('');onMounted(async()=>{try{data.value=await api('/dashboard')}catch(e:any){error.value=e.message}})
</script>
<template><div class="page-heading"><div><p class="eyebrow">CADA DÍA, UN TALLER MEJOR</p><h1>Hola, {{session.user?.name?.split(' ')[0]}} <span class="wave">✳</span></h1><p class="muted">Aquí está lo que está pasando en tu taller.</p></div><RouterLink v-if="session.user?.role==='ADMIN'" to="/orders?new=1" class="btn primary"><Icon name="plus"/>Nueva orden</RouterLink><RouterLink v-else to="/orders" class="btn primary">Ver mis servicios<Icon name="arrow"/></RouterLink></div><p v-if="error" class="error">{{error}}</p><div v-if="!data&&!error" class="loading">Cargando tu resumen…</div><template v-if="data"><section class="welcome-banner"><div><span class="capsule dark"><span class="status-dot"></span>TODO EN MARCHA</span><h2>Cada detalle cuenta.<br>Que nada se quede pendiente.</h2><RouterLink to="/orders">Revisar órdenes de servicio<Icon name="arrow" :size="18"/></RouterLink></div><div class="banner-art" aria-hidden="true"><div class="art-ring"></div><Icon name="car" :size="140"/><span class="art-tag"><Icon name="check" :size="16"/>Tu taller, conectado</span></div></section><section class="stats-grid"><article class="stat-card"><div class="stat-label">Servicios activos<span class="stat-icon mint"><Icon name="wrench"/></span></div><strong>{{data.active}}</strong><small>En proceso dentro del taller</small></article><article class="stat-card"><div class="stat-label">Listos para entregar<span class="stat-icon sand"><Icon name="check"/></span></div><strong>{{data.ready}}</strong><small>Un paso más cerca del camino</small></article><article class="stat-card"><div class="stat-label">Servicios entregados<span class="stat-icon lavender"><Icon name="car"/></span></div><strong>{{data.completed}}</strong><small>Órdenes completadas</small></article><article v-if="session.user?.role==='ADMIN'" class="stat-card"><div class="stat-label">Cobros de hoy<span class="stat-icon mint"><Icon name="wallet"/></span></div><strong class="money-stat">{{money(data.todayPayments)}}</strong><small>Ingresos netos de reembolsos</small></article></section><div class="dashboard-grid"><section class="panel"><div class="panel-heading"><div><h2>Actividad del taller</h2><p class="muted small">Las órdenes más recientes, a un vistazo.</p></div><RouterLink class="text-link" to="/orders">Ver todas<Icon name="arrow" :size="16"/></RouterLink></div><div class="table-wrap"><table><thead><tr><th>Orden / vehículo</th><th>Cliente</th><th>Estado</th></tr></thead><tbody><tr v-for="o in data.orders" :key="o.id"><td><RouterLink :to="'/orders/'+o.id" class="table-primary">#{{String(o.id).padStart(4,'0')}} · {{o.make}} {{o.model}}</RouterLink><small>{{o.license_plate||'Sin matrícula'}} · {{date(o.received_at)}}</small></td><td>{{o.customer_name}}</td><td><Badge :status="o.status"/></td></tr></tbody></table><div v-if="!data.orders.length" class="empty"><Icon name="orders" :size="38"/><h3>Tu próxima historia empieza aquí</h3><p>Crea una orden para empezar a organizar los servicios.</p></div></div></section><aside class="panel side-panel"><template v-if="session.user?.role==='ADMIN'"><div class="panel-heading"><h2>Atención al inventario</h2><span class="count-pill">{{data.lowStock?.length||0}}</span></div><div v-for="p in data.lowStock" :key="p.id" class="stock-row"><span class="stock-symbol"><Icon name="box"/></span><div><strong>{{p.name}}</strong><small>{{p.sku}}</small></div><span class="stock-amount">{{Number(p.stock)}}<small>mín. {{Number(p.minimum_stock)}}</small></span></div><div v-if="!data.lowStock?.length" class="empty compact"><Icon name="check" :size="32"/><p>No hay alertas de stock.</p></div><RouterLink to="/inventory" class="btn secondary full">Abrir inventario<Icon name="arrow" :size="16"/></RouterLink></template><template v-else><div class="panel-heading"><h2>Tu espacio personal</h2></div><div class="empty compact"><Icon name="shield" :size="40"/><h3>Información a tu alcance</h3><p>Consulta el avance, los trabajos realizados y el historial de tus servicios.</p></div><RouterLink to="/account" class="btn secondary full">Revisar mi cuenta</RouterLink></template></aside></div></template></template>
